Y12 = X12(:,p+1:end);
Z12 = [X12(:,p:end-1); X12(:,p-1:end-2)];
B12 = Y12 / Z12;
E12 = Y12 - B12 * Z12;

% GC 1 -> 2
Zred = Z12([2 4],:);
bred = Y12(2,:) / Zred;
ered = Y12(2,:) - bred * Zred;
GC_biv_1to2 = log(var(ered,1) / var(E12(2,:),1));

% GC 2 -> 1
Zred = Z12([1 3],:);
bred = Y12(1,:) / Zred;
ered = Y12(1,:) - bred * Zred;
GC_biv_2to1 = log(var(ered,1) / var(E12(1,:),1));

%% 4. ANALISI CONDIZIONATA: IL NODO 3 E INCLUSO
